### 1. **The 1000-Commit Limit and Commit Collection**

**File:** `/Users/soph/Work/entire/devenv/cli_experiments_2/cmd/entire/cli/strategy/common.go`
**Line 45:** Constant definition
```go
const MaxCommitTraversalDepth = 1000
```

**File:** `/Users/soph/Work/entire/devenv/cli_experiments_2/cmd/entire/cli/strategy/metadata_reconcile.go`
**Lines 241-275:** The `collectCommitChain` function (walks from tip to root following first parent, stops at shallow boundaries)
```go
// collectCommitChain walks from tip to root following first parent, returns oldest-first.
// Commits listed in shallow are treated as roots — the walk stops at them without
// traversing into their parents. go-git's repo.CommitObject().ParentHashes does not
// consult .git/shallow on its own, so without this check the walk would stroll past
// shallow boundaries into stale objects left in the pack (e.g., when the remote
// branch has been rebuilt since the last full fetch), producing a phantom chain of
// commits that no longer represent the actual checkpoint history.
func collectCommitChain(repo *git.Repository, tip plumbing.Hash, shallow map[plumbing.Hash]bool) ([]*object.Commit, error) {
	var chain []*object.Commit
	current := tip

	reachedRoot := false
	for range MaxCommitTraversalDepth {
		commit, err := repo.CommitObject(current)
		if err != nil {
			return nil, fmt.Errorf("failed to get commit %s: %w", current, err)
		}
		chain = append(chain, commit)

		if len(commit.ParentHashes) == 0 {
			reachedRoot = true
			break
		}
		if shallow[current] {
			// Shallow boundary — treat as a root.
			reachedRoot = true
			break
		}
		current = commit.ParentHashes[0]
	}

	if !reachedRoot {
		return nil, fmt.Errorf("commit chain exceeded %d commits without reaching root; aborting reconciliation", MaxCommitTraversalDepth)
	}

	// Reverse to oldest-first
	for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
		chain[i], chain[j] = chain[j], chain[i]
	}

	return chain, nil
}
```

**File:** `/Users/soph/Work/entire/devenv/cli_experiments_2/cmd/entire/cli/strategy/push_common.go`
**Lines 503-537:** The `collectCommitsSince` function (uses git rev-list for non-merge commits)
```go
// collectCommitsSince returns non-merge commits reachable from tip but not from
// exclude, ordered oldest-first in topological order.
func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()

	// cherryPickOnto computes each commit's delta against its first parent, so
	// replaying merge commits would incorrectly re-apply changes that arrived via
	// non-first-parent history. Limit the replay set to non-merge commits.
	cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
	cmd.Dir = repoPath
	output, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("git rev-list failed: %w", err)
	}

	lines := strings.Fields(string(output))
	if len(lines) > MaxCommitTraversalDepth {
		return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
	}

	commits := make([]*object.Commit, 0, len(lines))
	for _, line := range lines {
		hash := plumbing.NewHash(line)
		commit, commitErr := repo.CommitObject(hash)
		if commitErr != nil {
			return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
		}
		if len(commit.ParentHashes) > 1 {
			continue
		}
		commits = append(commits, commit)
	}

	return commits, nil
}
```

