96	// ReconcileDisconnectedMetadataRef detects and repairs disconnected local/remote
97	// metadata refs. Disconnected means no common ancestor, which
98	// only happens due to the empty-orphan bug. Diverged (shared ancestor) is normal
99	// and handled by the push path.
100	//
101	// Repair strategy: cherry-pick local commits onto remote tip, preserving all data.
102	// Checkpoint shards use unique paths (<id[:2]>/<id[2:]>/), so cherry-picks always
103	// apply cleanly.
104	//
105	// Progress messages are written to w (typically os.Stderr for hooks or
106	// cmd.ErrOrStderr() for commands).
107	// The remote ref can be either a remote-tracking ref or a temporary fetched ref.
108	func ReconcileDisconnectedMetadataRef(
109		ctx context.Context,
110		repo *git.Repository,
111		localRefName plumbing.ReferenceName,
112		remoteRefName plumbing.ReferenceName,
113		w io.Writer,
114	) error {
115		refs := checkpoint.ResolveCommittedRefs(ctx)
116		advance := func(hash plumbing.Hash) error {
117			return AdvanceLocalRef(ctx, repo, refs, localRefName, hash)
118		}
119	
120		// Check local ref
121		localRef, err := repo.Reference(localRefName, true)
122		if errors.Is(err, plumbing.ErrReferenceNotFound) {
123			return nil // No local ref — nothing to reconcile
124		}
125		if err != nil {
126			return fmt.Errorf("failed to check local metadata ref: %w", err)
127		}
128	
129		// Check remote-tracking or fetched ref
130		remoteRef, err := repo.Reference(remoteRefName, true)
131		if errors.Is(err, plumbing.ErrReferenceNotFound) {
132			return nil // No remote ref — nothing to reconcile
133		}
134		if err != nil {
135			return fmt.Errorf("failed to check remote metadata ref: %w", err)
136		}
137	
138		localHash := localRef.Hash()
139		remoteHash := remoteRef.Hash()
140	
141		// Same hash — nothing to do
142		if localHash == remoteHash {
143			return nil
144		}
145	
146		// Check if disconnected using git merge-base
147		repoPath, err := getRepoPath(repo)
148		if err != nil {
149			return err
150		}
151	
152		disconnected, err := isDisconnected(ctx, repoPath, localHash.String(), remoteHash.String())
153		if err != nil {
154			return fmt.Errorf("failed to check metadata ref ancestry: %w", err)
155		}
156		if !disconnected {
157			// Shared ancestry (diverged or ancestor) — not our problem
158			return nil
159		}
160	
161		// Disconnected — cherry-pick local commits onto remote tip
162		fmt.Fprintln(w, "[entire] Detected disconnected session metadata (local and remote share no common ancestor)")
163	
164		shallow, err := loadShallowHashes(ctx, repoPath)
165		if err != nil {
166			return fmt.Errorf("failed to load shallow boundaries: %w", err)
167		}
168	
169		// Collect local commits oldest-first
170		localCommits, err := collectCommitChain(repo, localHash, shallow)
171		if err != nil {
172			return fmt.Errorf("failed to collect local commits: %w", err)
173		}
174	
175		// Filter out empty-tree commits (the orphan bug commit)
176		var dataCommits []*object.Commit
177		for _, c := range localCommits {
178			tree, treeErr := c.Tree()
179			if treeErr != nil {
180				return fmt.Errorf("failed to read tree for commit %s: %w", c.Hash.String()[:7], treeErr)
181			}
182			if len(tree.Entries) > 0 {
183				dataCommits = append(dataCommits, c)
184			}
185		}
186	
187		if len(dataCommits) == 0 {
188			// Local only had empty orphan — just point to remote
189			if err := advance(remoteHash); err != nil {
190				return fmt.Errorf("failed to reset metadata ref to remote: %w", err)
191			}
192			fmt.Fprintln(w, "[entire] Done — local had no checkpoint data, reset to remote")
193			return nil
194		}
195	
196		fmt.Fprintf(w, "[entire] Cherry-picking %d local checkpoint(s) onto remote...\n", len(dataCommits))
197	
198		newTip, err := cherryPickOnto(ctx, repo, remoteHash, dataCommits, shallow)
199		if err != nil {
200			return fmt.Errorf("failed to cherry-pick local commits onto remote: %w", err)
201		}
202	
203		if err := advance(newTip); err != nil {
204			return fmt.Errorf("failed to update metadata ref: %w", err)
205		}
206	
207		fmt.Fprintln(w, "[entire] Done — all local and remote checkpoints preserved")
208		return nil
209	}
210	
211	// isDisconnected checks if two commits have no common ancestor using git merge-base.
212	// Returns (true, nil) if disconnected, (false, nil) if they share ancestry,
213	// or (false, error) if git merge-base failed for another reason.
214	//
215	// git merge-base exit codes:
216	//   - 0: common ancestor found (shared ancestry)
217	//   - 1: no common ancestor (disconnected)
218	//   - 128+: error (corrupt repo, invalid hash, etc.)
219	func isDisconnected(ctx context.Context, repoPath, hashA, hashB string) (bool, error) {
220		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
221		defer cancel()
222		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
223		cmd.Dir = repoPath
224		if err := cmd.Run(); err != nil {
225			var exitErr *exec.ExitError
226			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
227				return true, nil // No common ancestor — disconnected
228			}
229			return false, fmt.Errorf("git merge-base failed: %w", err)
230		}
231		return false, nil // Shared ancestry
232	}
233	
234	// collectCommitChain walks from tip to root following first parent, returns oldest-first.
235	// Commits listed in shallow are treated as roots — the walk stops at them without
236	// traversing into their parents. go-git's repo.CommitObject().ParentHashes does not
237	// consult .git/shallow on its own, so without this check the walk would stroll past
238	// shallow boundaries into stale objects left in the pack (e.g., when the remote
239	// branch has been rebuilt since the last full fetch), producing a phantom chain of
240	// commits that no longer represent the actual checkpoint history.
241	func collectCommitChain(repo *git.Repository, tip plumbing.Hash, shallow map[plumbing.Hash]bool) ([]*object.Commit, error) {
242		var chain []*object.Commit
243		current := tip
244	
245		reachedRoot := false
246		for range MaxCommitTraversalDepth {
247			commit, err := repo.CommitObject(current)
248			if err != nil {
249				return nil, fmt.Errorf("failed to get commit %s: %w", current, err)
250			}
251			chain = append(chain, commit)
252	
253			if len(commit.ParentHashes) == 0 {
254				reachedRoot = true
255				break
256			}
257			if shallow[current] {
258				// Shallow boundary — treat as a root.
259				reachedRoot = true
260				break
261			}
262			current = commit.ParentHashes[0]
263		}
264	
265		if !reachedRoot {
266			return nil, fmt.Errorf("commit chain exceeded %d commits without reaching root; aborting reconciliation", MaxCommitTraversalDepth)
267		}
268	
269		// Reverse to oldest-first
270		for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
271			chain[i], chain[j] = chain[j], chain[i]
272		}
273	
274		return chain, nil
275	}
276	
277	// loadShallowHashes returns the commit hashes listed in the repository's
278	// shallow file, or an empty map if the repository is not shallow.
279	func loadShallowHashes(ctx context.Context, repoPath string) (map[plumbing.Hash]bool, error) {
280		cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
281		cmd.Dir = repoPath
282		out, err := cmd.Output()
283		if err != nil {
284			return nil, fmt.Errorf("git rev-parse --git-common-dir: %w", err)
285		}
286		gitDir := strings.TrimSpace(string(out))
287		if !filepath.IsAbs(gitDir) {
288			gitDir = filepath.Join(repoPath, gitDir)
289		}
290		// Path is constructed from git's own --git-common-dir output, not user input.
291		data, err := os.ReadFile(filepath.Join(gitDir, "shallow")) //nolint:gosec // see comment above
292		if err != nil {
293			if errors.Is(err, os.ErrNotExist) {
294				return map[plumbing.Hash]bool{}, nil
295			}
296			return nil, fmt.Errorf("read shallow file: %w", err)
297		}
298		set := map[plumbing.Hash]bool{}
299		for _, line := range strings.Split(string(data), "\n") {
300			line = strings.TrimSpace(line)
301			if line == "" {
302				continue
303			}
304			set[plumbing.NewHash(line)] = true
305		}
306		return set, nil
307	}
308	
309	// cherryPickOnto applies each commit's delta onto base, building a linear chain.
310	// For each commit, it computes the full diff from its parent (additions, modifications,
311	// and deletions), then applies that delta onto the current tip's tree.
312	//
313	// Commits listed in shallow are treated as roots: their delta is computed against
314	// an empty tree rather than against their (past-the-boundary) parent. Without this,
315	// a shallow-boundary commit would be diffed against a stale parent tree whose
316	// objects live in the local pack but no longer represent the actual checkpoint
317	// history — producing nonsense changes when replayed onto the remote tip.
318	func cherryPickOnto(ctx context.Context, repo *git.Repository, base plumbing.Hash, commits []*object.Commit, shallow map[plumbing.Hash]bool) (plumbing.Hash, error) {
319		currentTip := base
320	
321		for _, commit := range commits {
322			changes, err := treeChangesForCherryPick(ctx, repo, commit, shallow)
323			if err != nil {
324				return plumbing.ZeroHash, err
325			}
326			if len(changes) == 0 {
327				continue // Skip no-op commits
328			}
329	
330			tipCommit, err := repo.CommitObject(currentTip)
331			if err != nil {
332				return plumbing.ZeroHash, fmt.Errorf("failed to get tip commit: %w", err)
333			}
334	
335			mergedTreeHash, err := checkpoint.ApplyTreeChanges(ctx, repo, tipCommit.TreeHash, changes)
336			if err != nil {
337				return plumbing.ZeroHash, fmt.Errorf("failed to apply cherry-pick changes: %w", err)
338			}
339	
340			// Create new commit on top of current tip, preserving original message/author
341			newHash, err := createCherryPickCommit(ctx, repo, mergedTreeHash, currentTip, commit)
342			if err != nil {
343				return plumbing.ZeroHash, fmt.Errorf("failed to create cherry-pick commit: %w", err)
344			}
345	
346			currentTip = newHash
347		}
348	
349		return currentTip, nil
350	}
351	
352	func treeChangesForCherryPick(ctx context.Context, repo *git.Repository, commit *object.Commit, shallow map[plumbing.Hash]bool) ([]checkpoint.TreeChange, error) {
353		commitTree, err := commit.Tree()
354		if err != nil {
355			return nil, fmt.Errorf("failed to get tree for commit %s: %w", commit.Hash, err)
356		}
357	
358		var parentTree *object.Tree
359		// Shallow-boundary commits are treated as roots — see cherryPickOnto for why.
360		if len(commit.ParentHashes) > 0 && !shallow[commit.Hash] {
361			parentCommit, pErr := repo.CommitObject(commit.ParentHashes[0])
362			if pErr != nil {
363				return nil, fmt.Errorf("failed to get parent commit %s: %w", commit.ParentHashes[0], pErr)
364			}
365			parentTree, err = parentCommit.Tree()
366			if err != nil {
367				return nil, fmt.Errorf("failed to get parent tree for commit %s: %w", commit.ParentHashes[0], err)
368			}
369		}
370	
371		changes, err := object.DiffTreeContext(ctx, parentTree, commitTree)
372		if err != nil {
373			return nil, fmt.Errorf("failed to diff commit %s against parent: %w", commit.Hash, err)
374		}
375	
376		treeChanges := make([]checkpoint.TreeChange, 0, len(changes))
377		for _, change := range changes {
378			treeChange, changeErr := changeToTreeChange(change)
379			if changeErr != nil {
380				return nil, fmt.Errorf("failed to convert change in commit %s: %w", commit.Hash, changeErr)
381			}
382			treeChanges = append(treeChanges, treeChange)
383		}
384		return treeChanges, nil
385	}
386	
387	func changeToTreeChange(change *object.Change) (checkpoint.TreeChange, error) {
388		action, err := change.Action()
389		if err != nil {
390			return checkpoint.TreeChange{}, fmt.Errorf("change action: %w", err)
391		}
392	
393		switch action {
394		case merkletrie.Insert, merkletrie.Modify:
395			entry := change.To.TreeEntry
396			return checkpoint.TreeChange{
397				Path: change.To.Name,
398				Entry: &object.TreeEntry{
399					Name: entry.Name,
400					Mode: entry.Mode,
401					Hash: entry.Hash,
402				},
403			}, nil
404		case merkletrie.Delete:
405			return checkpoint.TreeChange{Path: change.From.Name}, nil
406		default:
407			return checkpoint.TreeChange{}, fmt.Errorf("unsupported action %s", action)
408		}
409	}
410	
411	// createCherryPickCommit creates a new commit on top of parent, preserving the
412	// original commit's message and author.
413	func createCherryPickCommit(ctx context.Context, repo *git.Repository, treeHash, parent plumbing.Hash, original *object.Commit) (plumbing.Hash, error) {
414		committerName, committerEmail := GetGitAuthorFromRepo(repo)
415		now := time.Now()
416	
417		commit := &object.Commit{
418			TreeHash:     treeHash,
419			ParentHashes: []plumbing.Hash{parent},
420			Author:       original.Author,
421			Committer: object.Signature{
422				Name:  committerName,
423				Email: committerEmail,
424				When:  now,
425			},
426			Message: original.Message,
427		}
428	
429		checkpoint.SignCommitBestEffort(ctx, commit)
430	
431		obj := repo.Storer.NewEncodedObject()
432		if err := commit.Encode(obj); err != nil {
433			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
434		}
435	
436		hash, err := repo.Storer.SetEncodedObject(obj)
437		if err != nil {
438			return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
439		}
440	
441		return hash, nil
442	}
443	
444	// getRepoPath returns the filesystem path for the repository's worktree.
445	func getRepoPath(repo *git.Repository) (string, error) {
446		wt, err := repo.Worktree()
447		if err != nil {
448			return "", fmt.Errorf("failed to get worktree: %w", err)
449		}
450		return wt.Filesystem().Root(), nil
451	}
